/*********************************************************************/
/*********************************************************************/
/*                                                                   */
/* Name. . . : UTXSFS00                                              */
/* Type. . . : *NONE                                                 */
/*                                                                   */
/* Narrative : Format String to Left justify, Right justify, or      */
/*             Center within a given string length.                  */
/*                                                                   */
/*********************************************************************/
/**********------------ Program Maintenance Log ------------**********/
/*********************************************************************/
/* Personnel |   Date   | Comments/Description                       */
/*-----------|----------|--------------------------------------------*/
/* SYS3X/??? | ??/??/?? | Program Written                            */
/*           |          |                                            */
/*********************************************************************/
/*                                                                   */
             PGM        PARM(&PARMS)

             DCL        VAR(&PARMS )   TYPE(*CHAR) LEN(0518)

             DCL        VAR(&STRDTA)   TYPE(*CHAR) LEN(0512)
             DCL        VAR(&STRLEN)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&STRACT)   TYPE(*CHAR) LEN(0001)

             DCL        VAR(&BLANKS)   TYPE(*CHAR) LEN(0512)
             DCL        VAR(&BEGPOS)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&ENDPOS)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&LENGTH)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&BLKLEN)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&ADJUST)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&STRPOS)   TYPE(*DEC ) LEN(0005 0)
             DCL        VAR(&STROUT)   TYPE(*CHAR) LEN(0512)
/*                                                                   */
/*===================================================================*/
/* Unstring Parameters into fields.                                  */
/*===================================================================*/
             CHGVAR     VAR(&STRDTA) VALUE(%SST(&PARMS 0001 0512))
             CHGVAR     VAR(&STRLEN) VALUE(%SST(&PARMS 0513 0005))
             CHGVAR     VAR(&STRACT) VALUE(%SST(&PARMS 0518 0001))
/*                                                                   */
/*===================================================================*/
/* Check for errors in data sent.                                    */
/*===================================================================*/
             IF         COND(&STRDTA = &BLANKS) THEN(GOTO ENDPGM)
             IF         COND(&STRLEN = 000)     THEN(GOTO ENDPGM)
             IF         COND(&STRLEN > 512)     THEN(GOTO ENDPGM)
/*                                                                   */
/*===================================================================*/
/* Determine Beginning position of the String.                       */
/*===================================================================*/
             CHGVAR     VAR(&BEGPOS) VALUE(0)

BEGPOS:      CHGVAR     VAR(&BEGPOS) VALUE(&BEGPOS + 1)

             IF         COND(%SST(&STRDTA &BEGPOS 01) = ' ') THEN(DO)
             GOTO       CMDLBL(BEGPOS)
             ENDDO
/*                                                                   */
/*===================================================================*/
/* Determine the Endiing postion of the String                       */
/*===================================================================*/
             CHGVAR     VAR(&ENDPOS) VALUE(&STRLEN + 1)

ENDPOS:      CHGVAR     VAR(&ENDPOS) VALUE(&ENDPOS - 1)

             IF         COND(%SST(&STRDTA &ENDPOS 01) = ' ') THEN(DO)
             GOTO       CMDLBL(ENDPOS)
             ENDDO
/*                                                                   */
/*===================================================================*/
/* Calculate the Length and adjustment factor for the string         */
/*===================================================================*/
             CHGVAR     VAR(&LENGTH) VALUE(&ENDPOS - &BEGPOS + 1)
             CHGVAR     VAR(&BLKLEN) VALUE(&STRLEN - &LENGTH)
             CHGVAR     VAR(&ADJUST) VALUE(&BLKLEN /       2)

/*                                                                   */
/*===================================================================*/
/* By type determine the starting postion to place the string.       */
/*===================================================================*/
             IF         COND(&STRACT = 'L') THEN(DO)
             CHGVAR     VAR(&STRPOS) VALUE(00001)
             GOTO       CMDLBL(ADJUST)
             ENDDO

             IF         COND(&STRACT = 'R') THEN(DO)
             CHGVAR     VAR(&STRPOS) VALUE(&BLKLEN + 1)
             GOTO       CMDLBL(ADJUST)
             ENDDO

             CHGVAR     VAR(&STRPOS) VALUE(&ADJUST + 1)
/*                                                                   */
/*===================================================================*/
/* Adjust the string according to the starting postion.              */
/*===================================================================*/
 ADJUST:     CHGVAR     VAR(&STROUT) VALUE(&BLANKS)
             CHGVAR     VAR(%SST(&STROUT &STRPOS &LENGTH)) +
                      VALUE(%SST(&STRDTA &BEGPOS &LENGTH))
             CHGVAR     VAR(%SST(&PARMS 0001 0512)) VALUE(&STROUT)

 ENDPGM:     ENDPGM
